#!/usr/bin/env node
'use strict'

/**
 * Generates the standalone app's HTML pages from the server UI.
 *
 * Both share one UI — see the `hasLocalExporter()` seam in
 * `src/server/public/app.js`. Rather than hand-maintain a second copy of ~1900
 * lines of markup, the webapp entries are derived at build time: only the asset
 * paths change, plus one script tag publishing `window.LiaExporter`.
 *
 * Generated files are not committed; `webapp:dev` and `webapp:build` rebuild
 * them.
 */

const fs = require('fs')
const path = require('path')

const PUBLIC = path.join(__dirname, '..', 'src', 'server', 'public')
const WEBAPP = path.join(__dirname, '..', 'src', 'webapp')

/** Loads window.LiaExporter; must run before the page scripts that check it. */
const EXPORTER_SCRIPT = [
  '    <!-- Publishes window.LiaExporter, which switches the UI to exporting in',
  '         this tab instead of posting to the export service. Loads first. -->',
  '    <script type="module" src="main.ts"></script>',
].join('\n')

/**
 * Per-page rewrites. Paths are relative to src/webapp/, where the generated
 * files live, so shared assets point back into the server's public directory.
 */
const SHARED_REWRITES = [
  ['href="styles.css"', 'href="../server/public/styles.css"'],
  ['src="i18n.js"', 'src="../server/public/i18n.js"'],
  ['src="./assets/icon.svg"', 'src="../server/public/assets/icon.svg"'],
]

const PAGES = [
  {
    file: 'index.html',
    rewrites: [
      ...SHARED_REWRITES,
      [
        '    <script src="app.js"></script>',
        `${EXPORTER_SCRIPT}\n    <script src="../server/public/app.js"></script>`,
      ],
    ],
  },
  {
    file: 'status.html',
    rewrites: [
      ...SHARED_REWRITES,
      // status.html has no app.js; the bundle goes before its inline script.
      ['    <script>', `${EXPORTER_SCRIPT}\n    <script>`],
    ],
  },
]

for (const page of PAGES) {
  const source = path.join(PUBLIC, page.file)
  let html = fs.readFileSync(source, 'utf8')

  // Format tiles reference `../assets/…`, above the served root. A browser
  // clamps that to the root so it works on the server by accident, but a
  // bundler resolves it literally and fails.
  html = html.split('"../assets/').join('"../server/public/assets/')

  for (const [from, to] of page.rewrites) {
    if (!html.includes(from)) {
      console.error(
        `build-webapp-html: could not find ${JSON.stringify(from)} in ${path.relative(process.cwd(), source)}.\n` +
          'The server UI changed shape — update PAGES in this script.',
      )
      process.exit(1)
    }

    html = html.replace(from, to)
  }

  fs.writeFileSync(
    path.join(WEBAPP, page.file),
    `<!-- GENERATED by scripts/build-webapp-html.js — edit src/server/public/${page.file} instead. -->\n` +
      html,
  )
}

console.log(
  `webapp html  ${PAGES.map((p) => p.file).join(', ')} generated from src/server/public/`,
)
